#!/bin/bash
# 🛰️ Build the Orbit firmware and produce the deliverable.
#
# Produces:
#   orbit_firmware.bin            ← THE deliverable (project root, trimmed, ~7.7 MB)
#   firmware/release/             ← flash parts (bootloader/partition-table/ota_data/
#                                    orbit.bin = OTA payload) + FLASH.md + RELEASE.md
#   firmware/prebuilt/assets.bin  ← wake-word model image (raw esp-sr srmodels.bin)
#
# The full 16 MB image is NOT generated by default (rejected: too big, slow uploads).
# If ever needed:  python3 tools/make_full_image.py firmware/release/orbit_full_flash.bin --full
set -e
cd "$(dirname "$0")/.."          # orbit-assistant/
ROOT=$PWD
FW=$ROOT/firmware
REL=$FW/release

echo "=== 1/4 build firmware ==="
bash "$ROOT/tools/ensure_idf.sh"     # self-heal the IDF tree (sandbox snapshot cap)
set +e                               # export.sh has harmless non-zero internal returns
. /home/user/.cache/esp-idf/export.sh > /dev/null 2>&1
set -e
cd "$FW" && CMAKE_BUILD_PARALLEL_LEVEL=2 idf.py build

echo "=== 2/4 regenerate wake-word assets image ==="
cd "$ROOT" && python3 tools/build_assets.py

echo "=== 3/4 assemble the deliverable ==="
mkdir -p "$REL"
cp "$FW/build/bootloader/bootloader.bin"           "$REL/"
cp "$FW/build/partition_table/partition-table.bin" "$REL/"
cp "$FW/build/ota_data_initial.bin"                "$REL/"
cp "$FW/build/orbit.bin"                           "$REL/"   # app image = OTA payload for the portal
python3 tools/make_full_image.py "$ROOT/orbit_firmware.bin"   # THE deliverable (trimmed)

echo "=== 4/4 flash instructions ==="
cat > "$REL/FLASH.md" << 'EOF'
# 🛰️ Flashing Orbit

## One-file flash (the deliverable — trimmed image, ~7.7 MB, fast upload)
#   orbit_firmware.bin lives at the PROJECT ROOT (orbit-assistant/orbit_firmware.bin)
esptool.py --chip esp32s3 -b 921600 write_flash 0x0 orbit_firmware.bin
#   (first time after the old firmware: esptool.py erase_flash first)

## Or individual parts (all in this directory, except assets)
esptool.py --chip esp32s3 -b 921600 write_flash \
  0x0      bootloader.bin \
  0x8000   partition-table.bin \
  0xd000   ota_data_initial.bin \
  0x20000  orbit.bin \
  0x420000 ../prebuilt/assets.bin

## Monitor the boot log
idf.py -p /dev/ttyACM0 monitor
#   (or any serial monitor at 115200 baud)
EOF
echo "Deliverable ready: $ROOT/orbit_firmware.bin"
ls -la "$ROOT/orbit_firmware.bin" "$REL"

# Keep the persisted workspace lean: managed_components (69 MB) is regenerable —
# the component manager re-downloads it on the next build (~40 s). The sandbox
# workspace snapshot caps at ~128 MB and drops the biggest files first, which is
# how the release used to vanish between sessions.
rm -rf "$FW/managed_components"
